// Guard for the API reference (/docs/api, generated by scripts/qr-pages/build.py + apidocs.py from
// docs/api/openapi.json): spec copy in sync with the portal, every operation on every locale page,
// SEO limits, hreflang, JSON-LD, sitemap, llms, no inline code, no third-party scripts, no dashes in copy.
import test from "node:test";
import assert from "node:assert/strict";
import { readFileSync, existsSync } from "node:fs";

const ROOT = new URL("../", import.meta.url).pathname;
const PORTAL = `${ROOT}../podfy-portal/public/openapi.json`;
const LOCALES = ["", "nl/", "de/", "fr/"];
const decode = (s) => s.replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#x27;|&#39;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">");
const spec = JSON.parse(readFileSync(`${ROOT}docs/api/openapi.json`, "utf8"));
const ops = Object.entries(spec.paths).flatMap(([path, item]) =>
  ["get", "post", "put", "patch", "delete"].filter((m) => item[m]).map((m) => ({ method: m.toUpperCase(), path, id: item[m].operationId })));

test("docs/api/openapi.json equals the portal's public/openapi.json (skipped when the portal checkout is absent)", { skip: !existsSync(PORTAL) && "podfy-portal not checked out next to the site" }, () => {
  assert.equal(readFileSync(`${ROOT}docs/api/openapi.json`, "utf8"), readFileSync(PORTAL, "utf8"),
    "stale copy: run  node tools/sync-openapi.mjs && python3 scripts/qr-pages/build.py");
});

test("the spec copy is OpenAPI 3.1 with operations to document", () => {
  assert.match(spec.openapi, /^3\.1/);
  assert.ok(ops.length >= 7, `operations found: ${ops.length}`);
  assert.equal(new Set(ops.map((o) => o.id)).size, ops.length, "operationId must be unique");
});

test("every locale page lists every operation of the spec, with a curl example and the error table", () => {
  for (const loc of LOCALES) {
    const f = `${ROOT}${loc}docs/api/index.html`;
    assert.ok(existsSync(f), `missing ${f}`);
    const s = readFileSync(f, "utf8");
    for (const o of ops) {
      assert.ok(s.includes(`id="op-${o.id}"`), `${f}: operation ${o.id} missing`);
      assert.ok(s.includes(`<span class="api-method api-method-${o.method.toLowerCase()}">${o.method}</span> <code>${o.path.replace(/[{}]/g, (c) => c)}</code>`), `${f}: ${o.method} ${o.path} heading`);
    }
    assert.equal((s.match(/<article class="api-op"/g) || []).length, ops.length, `${f}: article count`);
    assert.equal((s.match(/<pre class="api-code">/g) || []).length, ops.length + 1, `${f}: curl examples (+1 in the intro)`);
    assert.match(s, /id="error-codes"/);
    assert.match(s, /href="\/docs\/api\/openapi\.json"/, `${f}: download link`);
    assert.match(s, /pk_live_/); assert.match(s, /pk_test_/); assert.match(s, /600/); assert.match(s, /next_cursor/);
  }
});

test("API pages: title and description limits, canonical, hreflang x4, indexable, JSON-LD", () => {
  for (const loc of LOCALES) {
    const f = `${ROOT}${loc}docs/api/index.html`;
    const s = readFileSync(f, "utf8");
    const title = decode(s.match(/<title>(.*?)<\/title>/)[1]);
    const desc = decode(s.match(/<meta name="description" content="(.*?)"/)[1]);
    assert.ok(title.length <= 60, `${f}: title ${title.length} chars`);
    assert.ok(desc.length <= 155 && desc.length >= 60, `${f}: description ${desc.length} chars`);
    assert.match(s, new RegExp(`<link rel="canonical" href="https://podfy.net/${loc}docs/api/"`));
    assert.equal((s.match(/rel="alternate" hreflang="/g) || []).length, 5, `${f}: hreflang`);
    for (const l of ["en", "nl", "de", "fr"]) assert.match(s, new RegExp(`hreflang="${l}" href="https://podfy.net/${l === "en" ? "" : l + "/"}docs/api/"`), `${f}: hreflang ${l}`);
    assert.match(s, /hreflang="x-default" href="https:\/\/podfy.net\/docs\/api\/"/);
    assert.match(s, /<meta name="robots" content="index,follow/);
    assert.match(s, /"@type": "TechArticle"/); assert.match(s, /"@type": "BreadcrumbList"/);
    assert.match(s, new RegExp(`<html lang="${loc ? loc.slice(0, 2) : "en"}"`));
  }
});

test("API pages: no inline style or script, no third-party scripts or API explorers, no em/en dashes in copy", () => {
  for (const loc of LOCALES) {
    const f = `${ROOT}${loc}docs/api/index.html`;
    const s = readFileSync(f, "utf8");
    assert.doesNotMatch(s, /\sstyle=/, `${f}: inline style`);
    for (const m of s.matchAll(/<script\b([^>]*)>/g)) {
      const a = m[1];
      assert.ok(/type="application\/ld\+json"/.test(a) || /\bsrc="\/assets\//.test(a), `${f}: script not allowed: <script${a}>`);
    }
    assert.doesNotMatch(s, /swagger|redoc|unpkg|jsdelivr|cdnjs/i, `${f}: API explorer or CDN`);
    assert.doesNotMatch(s, /\son(click|load|error)=/, `${f}: inline handler`);
    const body = s.replace(/<script[\s\S]*?<\/script>/g, "").replace(/<title>.*?<\/title>/, "");
    assert.doesNotMatch(body, /[–—]/, `${f}: em/en dash in copy`);
  }
});

test("translated intros keep their register: NL je, DE Sie, FR vous; the reference stays English and says so", () => {
  const text = (loc) => decode(readFileSync(`${ROOT}${loc}docs/api/index.html`, "utf8").replace(/<script[\s\S]*?<\/script>/g, "").replace(/<[^>]+>/g, " "));
  const nl = text("nl/"), de = text("de/"), fr = text("fr/");
  const word = (w, f = "") => new RegExp(`(?<![\\p{L}])(${w})(?![\\p{L}])`, "u" + f); // unicode-aware \b (JS \b treats e-circumflex as a boundary)
  assert.match(nl, word("je")); assert.doesNotMatch(nl, word("u|uw|U|Uw"), "nl: formal u/uw");
  assert.match(de, word("Sie")); assert.doesNotMatch(de, word("du|dich|dein|deine|deinen", "i"), "de: informal du");
  assert.match(fr, word("vous")); assert.doesNotMatch(fr, word("tu|toi|ton|ta|tes", "i"), "fr: informal tu");
  for (const [l, t] of [["nl", nl], ["de", de], ["fr", fr]]) assert.match(t, /openapi\.json/, `${l}: download`);
  assert.match(nl, /staat in elke taal in het Engels/); assert.match(de, /in jeder Sprache auf Englisch/); assert.match(fr, /reste en anglais dans toutes les langues/);
  for (const loc of ["nl/", "de/", "fr/"]) assert.match(readFileSync(`${ROOT}${loc}docs/api/index.html`, "utf8"), /id="op-listRecords"/);
});

test("sitemap lists /docs/api/ in every locale; llms files and the footer mention it", () => {
  const xml = readFileSync(`${ROOT}sitemap.xml`, "utf8");
  for (const loc of LOCALES) assert.ok(xml.includes(`<loc>https://podfy.net/${loc}docs/api/</loc>`), `${loc}: not in sitemap`);
  assert.match(readFileSync(`${ROOT}llms.txt`, "utf8"), /https:\/\/podfy.net\/docs\/api\//);
  const full = readFileSync(`${ROOT}llms-full.txt`, "utf8");
  assert.match(full, /Source: https:\/\/podfy.net\/docs\/api\//);
  for (const o of ops) assert.ok(full.includes(`${o.method} ${o.path} (scope`), `llms-full: ${o.method} ${o.path}`);
  assert.match(readFileSync(`${ROOT}partials/footer.html`, "utf8"), /href="\/docs\/api\/">API reference</);
});

test("deploy.sh publishes docs/api (page and spec) but still keeps the internal docs/ out", () => {
  const d = readFileSync(`${ROOT}deploy.sh`, "utf8");
  assert.match(d, /--include '\/docs\/api\/openapi\.json'/);
  assert.match(d, /--exclude '\/docs\/\*'/);
  assert.doesNotMatch(d, /--exclude 'docs'/, "an unanchored docs exclude would also drop /docs/api and /nl/docs/api");
});

test("pages that mention the Open API link to the reference of their own locale", () => {
  for (const loc of LOCALES) {
    for (const f of ["cmr/index.html", "pricing.html", "solutions/qr-issue-reporting/index.html", "index.html"]) {
      const s = readFileSync(`${ROOT}${loc}${f}`, "utf8");
      assert.match(s, new RegExp(`<a href="/${loc}docs/api/">(Open API|Offene API|API ouverte)</a>`), `${loc}${f}: no link to /${loc}docs/api/`);
    }
  }
});
